import { d } from './full-schema.mjs';

// Paired biographical essays extend the formation/activity/assessment entries.
// Participation is recorded separately in the cited person–event action tables.
export const biographyDossiers = {
  'lin-zexu': [
    d('禁烟官僚的政策选择', 'An official’s choices over opium',
      '林则徐的禁烟并非一般意义上的反对一切海外交流，而是从清朝法律、财政和社会秩序出发处理鸦片输入。1839年在广州要求交出鸦片、组织销毁，使问题从地方缉私上升为国家交涉。对外国商人的约束、对中国吸食者的处罚和沿海防务属于不同政策环节，成败不能只用虎门销烟一个象征衡量。\n\n他搜集海外知识并尝试了解英国，说明抵抗与学习能够共存；但对英国政治、军事及商业网络的认识仍受资料与翻译条件限制。禁烟具有公共健康和主权依据，具体执行与战争准备则仍可分别评价。',
      'Lin approached opium through Qing law, finance and social order rather than a categorical rejection of overseas contact. His 1839 demand for surrender and destruction of opium turned local enforcement into interstate confrontation. Merchant restrictions, punishment of Chinese users and coastal defense were different policies.\n\nHe also gathered foreign information. Resistance and learning could coexist, although translation and available evidence limited his understanding of British power. The public-health and sovereignty grounds of prohibition do not settle questions about implementation or military preparation.', ['lin-letter', 'opium-trade', 'opium-war']),
    d('失势、边疆与后来纪念', 'Dismissal, frontier service and later memory',
      '战局失利后，清廷将责任集中到林则徐等官员，林被革职并发往新疆。他的经历显示帝国行政可以把复杂的财政、技术与外交失败压缩为个人问责。此后边疆治理和再次任用，也使其生涯不能止于1839年。\n\n后来纪念把他塑造成抵抗外来侵略的典范，这一地位有明确行动基础，但不应因此假设清廷已经拥有后来民族国家的全部观念。阅读致英国君主的信还需区分撰写、传递和对方实际收到，不能以一份文本直接证明外交沟通已经完成。',
      'After military setbacks, the court dismissed Lin and sent him to Xinjiang, concentrating responsibility for a wider institutional failure on officials. Frontier service and later employment continued his career beyond 1839.\n\nHis later status as a symbol of resistance rests on identifiable actions, but Qing political concepts should retain their historical setting. A letter’s composition, transmission and receipt are separate matters: its survival does not prove that communication with the British monarch was completed.', ['lin-letter', 'opium-war', 'qing-overview']),
  ],
  'li-hongzhang': [
    d('地方军政资源与近代事业', 'Regional power and modernization',
      '李鸿章通过淮军及平定太平天国战争建立军政地位，随后在外交、海防和实业中长期居于核心。兵工、轮船、电报与海军事业需要官款、商股、外国技术和人才共同支撑，既不是单个人凭空创造，也不能以官商关系复杂便否认制度试验。\n\n地方财政和个人网络提高调动能力，却使全国统一配置与监督困难。北洋建设的得失因此应比较采购、训练、维修和持续经费，不能把一艘新舰下水当作整个体系已经成熟。',
      'Li’s Huai Army and role in the Taiping war supported a career spanning diplomacy, maritime defense and enterprise. Arsenals, shipping, telegraphs and naval construction combined public finance, commercial investment, foreign technology and trained personnel.\n\nRegional networks aided mobilization while complicating national coordination and oversight. Procurement, training, maintenance and recurring budgets are therefore essential to evaluating the Beiyang system; launching a modern ship did not establish a mature organization.', ['military-lateqing', 'qing-overview', 'sino-japanese']),
    d('战败后的谈判与责任', 'Negotiation and responsibility after defeat',
      '甲午战败后，李鸿章参加马关谈判并承受屈辱性条款的政治责任。谈判中的行动能力受到前线失败、清廷选择和日本强制条件限制；签字者不能自动等同唯一战争责任者。相反，长期掌握军政资源也使他不能只以奉命办事脱离此前建设和协调责任。\n\n1900年前后的外交继续体现维持王朝、保全地方和面对列强压力的多重目标。卖国者或现代化先驱两种单一标签都会遗漏具体选择，应将不平等条件、可行替代与其实际权限放在同一评价中。',
      'Defeat in 1895 constrained Li’s Shimonoseki negotiations. Front-line losses, court decisions and Japanese coercion limited his alternatives; the signatory was not the sole author of the war’s outcome. His long control of military resources nevertheless carries responsibilities beyond simply obeying instructions.\n\nDiplomacy around 1900 again combined dynastic preservation, regional interests and foreign pressure. Neither a traitor label nor an unqualified modernization narrative explains these choices without examining authority, alternatives and unequal bargaining conditions.', ['shimonoseki', 'sino-japanese', 'boxer-siege']),
  ],
  'cixi': [
    d('宫廷权力与改革的选择性', 'Court power and selective reform',
      '慈禧的长期影响来自摄政安排、官员任用和宫廷联盟，不能仅以性格解释。她所处的政治系统需要在军事危机、财政约束与皇权秩序之间选择，曾支持部分自强事业，也在1898年打断快速改革并重新控制权力。支持器物建设与限制政治改变并不矛盾，恰好反映选择性改革。\n\n把光绪与慈禧之间的分歧写成现代民主与专制的简单对决并不准确，双方改革设想仍围绕王朝。真正需要解释的是措施、节奏、任用及权力分配为何引发冲突。',
      'Cixi’s influence rested on regency arrangements, appointments and court alliances. She supported some self-strengthening projects yet halted rapid reform in 1898 and regained control. Technical development and resistance to changes in political authority could coexist.\n\nThe conflict with Guangxu was not a straightforward contest between modern democracy and autocracy: both operated within dynastic projects. Measures, timing, personnel and the distribution of authority explain their disagreement more precisely than personal temperament alone.', ['qing-court-photos', 'kang-memorial', 'qing-edict', 'military-lateqing']),
    d('1900年的失策与清末新政', 'The 1900 crisis and subsequent reforms',
      '义和团危机中，清廷对民间武装、外国压力和朝中分歧的判断失当，支持对外战争的决策扩大灾难。此责任需要明确，同时须保留各省督抚、军队和列强自身行动的区别。逃离北京与随后赔款，使王朝的财政和权威进一步受损。\n\n1901年后的新政说明晚年慈禧并非拒绝一切变化，但改教育、军队和行政也不足以消除政治信任危机。后来的照片、戏剧与传闻常把她极端妖魔化或浪漫化，宫廷影像尤其不能独立证明民众生活和全国施政效果。',
      'Court misjudgment during the Boxer crisis, including support for war against foreign powers, amplified catastrophe. Responsibility should remain explicit while distinguishing provincial officials, military units and foreign actions. Flight from Beijing and subsequent indemnities further damaged dynastic finances and authority.\n\nPost-1901 reforms changed education, military organization and administration without resolving political distrust. Court photographs and later dramatic portrayals reveal representations of power; they cannot independently establish nationwide policy effects or ordinary living conditions.', ['boxer-siege', 'qing-edict', 'qing-court-photos']),
  ],
  'sun-yatsen': [
    d('革命网络与1912年的妥协', 'Revolutionary networks and the 1912 compromise',
      '孙中山的政治资源连接海外华人筹款、革命组织与国内起义者，屡次失败说明1911年成功并非一套计划的顺利兑现。武昌起义由当地力量发动，各省响应和清廷危机共同促成政体转换。孙担任临时大总统具有象征和组织意义，却没有独立控制全国军队。\n\n让位袁世凯是以有限军事资源争取清帝退位及共和统一的妥协。它保留了废除帝制的成果，也把新制度置于北洋权力与薄弱议会条件之下，不能仅以个人无私或识人失误解释全部后果。',
      'Sun linked diaspora fundraising, revolutionary organizations and domestic insurgents. Repeated failures preceded 1911, whose Wuchang uprising and provincial responses were not simply execution of his central plan. His provisional presidency carried symbolic authority without command of all armies.\n\nYielding to Yuan Shikai sought abdication and republican unity under military constraints. It preserved the end of monarchy while leaving the new system dependent on Beiyang power and weak parliamentary institutions. Personal generosity or misjudgment alone cannot explain the outcome.', ['sun-museum', 'revolution-1911', 'republic-sources']),
    d('党国建设、合作与未完成方案', 'Party-building, cooperation and unfinished plans',
      '共和国初期反袁及此后护法挫折，使孙更重视党组织、军事力量和革命阶段论。1920年代与苏联合作、改组国民党及容纳共产党人，扩大动员基础，也形成后来分裂的组织条件。民族、民权、民生三项主张在不同时期解释变化，不宜当作从始至终不变的一份政策清单。\n\n军政、训政到宪政的阶段设想把最终宪政目标与过渡时期集权并置，监督和结束过渡的机制因此成为关键问题。1925年去世后各方争夺其遗产，不能把后来所有以其名义实行的政策都倒认作他已经批准。',
      'Failures against Yuan and in constitutional-protection politics increased Sun’s emphasis on party organization, armies and staged revolution. Cooperation with the Soviet Union and Communist participation in the reorganized Nationalist Party broadened mobilization while creating conditions for later conflict.\n\nHis military, tutelary and constitutional stages combined an eventual constitutional goal with concentrated transitional authority. How transition would be supervised and ended remained central. After his death in 1925, competing claims to his legacy cannot establish his approval of subsequent policies.', ['sun-stages', 'sun-democracy', 'sun-museum', 'split-1927']),
  ],
  'yuan-shikai': [
    d('新军、退位谈判与总统权力', 'The New Army, abdication and presidential power',
      '袁世凯从晚清新军和地方行政中形成北洋网络，训练与组织改革使其拥有可与朝廷谈判的军事资源。1911年后，他同时面对清廷、革命各省、外国利益与部下，并利用自身居间地位取得总统职位。清帝退位不是他单方面赐予的改革，也不是没有他即可按相同方式发生的简单事实。\n\n共和国需要议会、法律和地方政治合作，袁却更倾向以军政控制处理冲突。宋教仁遇刺后的责任争议应依具体证据讨论，而此后压制国民党、解散议会与集中权力属于另有记录的政治进程。',
      'Yuan built the Beiyang network through late-Qing military and administrative reform. After 1911 he negotiated among the court, revolutionary provinces, foreign interests and his officers, using this position to secure the presidency. Abdication was a negotiated outcome rather than his unilateral gift.\n\nHe increasingly met republican conflicts through military and executive control. Questions about responsibility for Song Jiaoren’s assassination require specific evidence; suppression of the Nationalists, dissolution of parliament and concentration of power form a separately documented political sequence.', ['revolution-1911', 'song-assassination', 'republic-sources']),
    d('帝制失败及其结构遗产', 'Failed monarchy and its institutional legacy',
      '二十一条交涉发生于日本利用欧洲战争扩张影响的环境，袁政府承受最后通牒并接受部分要求，但初稿、修改案与正式文件必须区分。外交受压与国内政治选择又相互作用，不能以外国压力为后来称帝自动开脱。\n\n恢复帝制破坏共和合法性，引发护国反对和北洋内部离心，袁最终取消帝制并于1916年去世。此后军阀分裂既承接个人网络，也来自财政、地方军力与宪政失灵。其死亡结束个人统治，却没有自动解决造成集权的制度条件。',
      'Japan exploited the European war during the Twenty-One Demands negotiations. Yuan’s government accepted some demands under ultimatum; initial proposals and binding texts must remain distinct. Foreign pressure does not excuse his subsequent choice of monarchy.\n\nThe imperial project undermined republican legitimacy and triggered opposition and military defections. Its cancellation preceded Yuan’s death in 1916. Subsequent fragmentation reflected personal networks, fiscal divisions and failed constitutional constraints; his death did not remove these structures.', ['twentyone-doc', 'republic-sources', 'northern-finance']),
  ],
  'chen-duxiu': [
    d('从文化批评到政党组织', 'From cultural criticism to party organization',
      '陈独秀以《新青年》推动对礼教、家庭权威和思想习惯的批判，民主与科学是其早期语言的重要部分。五四前后对国际秩序、社会改造和马克思主义的认识改变，使他从文化启蒙进入共产党组织。此转向并非所有新文化参与者共同作出的选择，胡适等人的道路不同。\n\n作为早期总书记，他面对工人动员、国共合作与共产国际指导之间的张力。组织发展依靠真实的社会活动，也存在对外部资源和战略判断的依赖，不能把政党史完全缩成几个人在一处会面的建党场景。',
      'Through New Youth, Chen challenged inherited authority in thought, family and social conventions. Democracy and science marked his early language. Around May Fourth, Marxism and changing views of international order drew him toward Communist organization, a path not shared by all New Culture participants.\n\nAs an early general secretary he confronted tensions among worker mobilization, cooperation with the Nationalists and Comintern direction. Party formation involved wider social organizing and strategic dependence, not simply a founding meeting.', ['chen-awakening', 'ccp-formation', 'republic-sources']),
    d('1927年失败与后来的异议', 'The 1927 defeat and later dissent',
      '国共分裂后，陈被追究右倾责任并失去领导地位，后来又因托洛茨基主义活动被开除。判断1927年失败不能只接受胜利路线后来形成的个人归罪，上海和武汉局势、蒋介石及汪精卫行动、共产国际指示和党内判断都必须纳入。\n\n他在后半生重新反思独裁、革命与民主，说明一个人的思想并非随失势停止。早期启蒙、革命组织责任和后来批判可以放在连续生涯中理解，既不因异议抹掉党内经历，也不因早期身份否认后来的变化。',
      'After the 1927 rupture, Chen lost leadership and was later expelled over Trotskyist activity. Responsibility cannot be reconstructed solely through later victorious party narratives: Nationalist actions, Shanghai and Wuhan conditions, Comintern instructions and Communist judgments all mattered.\n\nHis later reflections on dictatorship, revolution and democracy show an intellectual career continuing after political defeat. Early enlightenment, organizational responsibility and subsequent dissent belong in one changing biography rather than mutually exclusive identities.', ['split-1927', 'chen-awakening', 'ccp-formation']),
  ],
  'chiang-kai-shek': [
    d('军队、政党与战时领导', 'Army, party and wartime leadership',
      '蒋介石借黄埔、北伐及党内竞争建立最高权力，但南京政府始终需要与地方实力派协商。1927年的清共暴力是其政治上升的重要组成，国家建设与镇压同时发生。新生活运动、行政整顿和军队整合体现其秩序目标，不能据口号直接推定社会已被完全控制。\n\n抗日战争中，他领导国民政府正面战场及盟国外交，承担长期消耗与战略决策。1938年黄河决口的军令责任、撤退和征粮造成的民众代价，也必须纳入战时领导评价，抵抗贡献不使具体伤害失去追问意义。',
      'Chiang consolidated power through Whampoa, the Northern Expedition and party conflict, while still bargaining with regional commanders. The violence of the 1927 purge accompanied state-building. His New Life Movement and administrative campaigns expressed a pursuit of order without proving complete social control.\n\nDuring the war he led the Nationalist government, major conventional fronts and Allied diplomacy. Command responsibility for the 1938 Yellow River breach and civilian costs of retreat and requisition remain part of this record alongside resistance.', ['split-1927', 'chiang-newlife', 'resistance-war', 'yellowriver-1938']),
    d('大陆失败、台湾统治与分裂遗产', 'Mainland defeat, Taiwan rule and division',
      '战后与共产党谈判、整军争议及内战升级，不能只按后来失败倒推每次选择都毫无现实依据；但通胀、军事误判、党国腐败与政治排斥确实削弱支持。1949年后迁台的政权重新组织财政、土地和军队，也延续戒严、白色恐怖及党国控制。\n\n二二八与后续镇压必须区分陈仪地方处置、中央增兵批准和各部队行动，不能借地方责任免除蒋的最高权力角色。台湾经济发展与受害者权利均属于其统治遗产，不能以增长抵销迫害，也不能把后来民主转型提前归给其任内已经完成。',
      'Postwar negotiations and military choices should be examined before assuming defeat was inevitable. Inflation, strategic errors, corruption and political exclusion nevertheless weakened Nationalist support. After 1949, reorganization in Taiwan accompanied martial law, the White Terror and party-state control.\n\nResponsibility for February 28 distinguishes Chen Yi’s local decisions, central authorization of reinforcements and military action without erasing Chiang’s supreme authority. Development and victims’ rights both belong to his legacy; later democratization should not be projected backward into his rule.', ['civilwar-study', 'frus-1946', '228-responsibility', 'taiwan-white-terror', 'taiwan-republic']),
  ],
  'wang-jingwei': [
    d('革命资历与1927年的决裂', 'Revolutionary standing and the 1927 rupture',
      '汪精卫早期参加反清活动，革命资历与孙中山身后国民党竞争使其具有独立政治地位。他在武汉时期一度与共产党合作，随后转向清共，说明国共分裂不是只有上海一个地点、蒋一个行动者。地方军力、社会动员和共产国际路线共同影响武汉决策。\n\n汪与蒋的长期竞争涉及党权、路线和领导资格，不能将全部政治选择解释为嫉妒。了解其革命身份有助解释后来合作政权为何试图争夺正统，也不为与侵略者合作提供道德豁免。',
      'Wang’s anti-Qing activities and revolutionary standing gave him an independent position after Sun’s death. His Wuhan government first cooperated with Communists and then purged them, showing that the 1927 rupture involved more than Shanghai and Chiang alone.\n\nCompetition with Chiang concerned authority, strategy and claims to succession, not simply personal jealousy. Revolutionary credentials later helped Wang claim legitimacy, but do not excuse collaboration with an invading power.', ['split-1927', 'sun-museum', 'wang-collaboration']),
    d('合作政权的约束与战争责任', 'Collaboration, constraints and responsibility',
      '汪离开重庆后在日本扶持下于1940年建立南京政权，以和平和减少战争损失为自己辩护。此论述需要与占领事实比较：日军控制、治外权力、资源征取和军事行动限制其自主性。地方行政仍有活动空间，却不能因此把合作政权描述为与重庆具有同等独立性的国家。\n\n合作者的动机可能包含政治计算、反共与止战想法，但动机不等于实际结果。参与占领秩序及镇压的责任应按机构与行动追踪，不能只用汉奸称号代替研究，也不能以复杂性淡化侵略及其造成的伤害。',
      'Wang’s Japanese-sponsored Nanjing regime began in 1940, presenting collaboration as peace and a reduction of suffering. Japanese military control, extraction and reserved powers sharply limited autonomy, even where local administration retained some discretion.\n\nPolitical calculation, anti-communism and a claimed wish to end war may explain motives without establishing beneficial results. Responsibility requires tracing institutions and actions rather than relying solely on a traitor label; complexity should not obscure occupation or its violence.', ['wang-collaboration', 'war-occupation', 'resistance-war']),
  ],
  'zhang-xueliang': [
    d('东北易帜与失去东北', 'Northeast allegiance and the loss of Manchuria',
      '张学良继承东北军及地方政权后改旗归属南京，在名义统一中保留地方军事基础。1931年日军侵占东北时，中国军队未组织充分抵抗，张及中央对冲突、国际干预和可用兵力的判断应分别检验。关于具体不抵抗命令来源，不能以一段晚年口述取代全部同期记录。\n\n东北沦陷损害其政治基础，也使东北军官兵的返乡愿望影响后来选择。失去领土既是侵略结果，也暴露中央与地方协调问题；承认后者不能转移日本发动侵略的责任。',
      'After inheriting the northeastern military and government, Zhang recognized Nanjing while retaining a regional base. During the 1931 invasion, inadequate resistance raises separate questions about his decisions and central expectations concerning escalation and international intervention. Later recollection alone cannot resolve every order.\n\nLoss of Manchuria damaged his authority and strengthened soldiers’ desire to return home. It exposed coordination failures without transferring responsibility away from Japan for initiating aggression.', ['mukden', 'republic-sources', 'accidental-holyland']),
    d('西安事变后的个人与国家结局', 'Personal and national consequences of Xi’an',
      '1936年张学良与杨虎城扣押蒋介石，意图迫使停止内战、共同抗日，行动同时带来兵变和更大内战的风险。中共、南京各派及国际因素促成和平解决；不能以最后结果假设当时所有参与者都已预知会成功。\n\n张送蒋返回南京后遭长期拘禁，其余生与杨虎城后来被杀的命运不同。个人承担重大代价不消除前期军政责任，也不否认西安解决为第二次合作创造空间。两者需要按年代相接，避免只用爱国英雄或失败军阀一个身份覆盖整个人生。',
      'In 1936 Zhang and Yang Hucheng detained Chiang to force an end to civil war and resistance to Japan. The action also risked military escalation. Communist, Nationalist and international interventions helped produce a peaceful resolution whose success was not predetermined.\n\nZhang accompanied Chiang to Nanjing and entered prolonged confinement, a fate different from Yang’s later killing. His personal cost and the opening toward renewed cooperation belong alongside earlier responsibilities rather than replacing them.', ['xian-site', 'accidental-holyland', 'civilwar-study']),
  ],
  'song-meiling': [
    d('跨国沟通与战时公共角色', 'Transnational communication and wartime roles',
      '宋美龄的英语教育、宗教和家庭网络使她能够在国民政府与美国社会之间沟通。战时演说、外访和慈善活动将中国抗战呈现给海外公众，争取支持的影响需要联系美国政策、军事条件与其他外交者，而非只归因于个人魅力。\n\n她并非没有政治行动的第一夫人，也不能因此被推定为每项军令的共同签署者。航空、妇女组织、救济与外交宣传各有制度渠道，研究应区分公开代表、资源协调和正式指挥权限。',
      'Soong May-ling’s English-language education, religion and family networks supported communication with American society. Speeches, visits and charity presented China’s resistance abroad, within constraints imposed by American policy and military conditions.\n\nShe was a political actor rather than merely a ceremonial spouse, but this does not establish her authorship of every command. Aviation, women’s organizations, relief and publicity involved different institutions; representation, coordination and formal command must be distinguished.', ['resistance-war', 'cairo', 'taiwan-republic']),
    d('家族、党国与历史形象', 'Family, party-state and historical representation',
      '宋氏家族连接政治、金融和国际资源，既提高动员能力，也引发权力集中和利益关系的质疑。评价应追踪可证实的财政和行政安排，不能把所有经济失败都说成某一家族私吞，也不能用优雅形象排除利益冲突研究。\n\n战后迁台及长期海外活动延续其公众影响，而对她的书写常受性别、容貌和婚姻叙事支配。个人外交贡献、对威权政权的支持及所处权力网络可同时讨论，不应以性别化讥讽代替对政治责任的分析。',
      'The Soong family connected political, financial and international resources, aiding mobilization while raising questions about concentrated power and interests. These require documented arrangements rather than assumptions that every failure resulted from a family’s private enrichment.\n\nHer postwar public influence continued across Taiwan and overseas life. Accounts centered on appearance and marriage can obscure both diplomatic work and support for an authoritarian order. Political responsibility deserves analysis without gendered caricature.', ['resistance-war', 'civilwar-study', 'taiwan-republic']),
  ],
  'john-rabe': [
    d('安全区中的有限保护', 'Limited protection within the Safety Zone',
      '拉贝是德国商人，也是纳粹党成员，这两项身份都不能从传记中删去。1937年南京危机中，他参与领导安全区组织，以外国身份、交涉和现场干预帮助平民。安全区能够提供部分庇护，却没有阻止日军进入、掳人和施暴，保护并非绝对有效。\n\n其救助说明个人可以在有限制度空间内作出重要选择，但安全区同样依靠中国工作人员、其他外侨及居民劳动。把一切救援集中为一位外国救世主，会使实际维持食物、卫生和秩序的共同工作消失。',
      'Rabe was both a German businessman and a Nazi Party member; neither identity should be omitted. In Nanjing in 1937 he helped lead the Safety Zone and intervened for civilians. Protection was limited: Japanese troops still entered, seized people and committed violence.\n\nHis choices mattered within constrained institutions, alongside Chinese staff, other foreigners and residents who sustained food, sanitation and shelter. A single-rescuer story would obscure this collective work.', ['nanjing-archive', 'resistance-war']),
    d('日记的见证能力与边界', 'What the diaries can establish',
      '拉贝日记保存当时所见、接获报告和交涉线索，对重建南京暴行具有重要价值。日记中的亲见、转述和估计必须区分，其位置也不能覆盖城内外所有地点。与魏特琳、其他安全区文件、日军材料及审判记录比较，可检验时间和行动。\n\n回国后尝试传播所知与其所处德国政治环境有关，个人救助行为不等于纳粹制度本身具有人道性质。历史评价可以明确肯定其保护平民的行动，同时保留其政治身份和资料范围，避免以某一面消除另一面。',
      'Rabe’s diaries preserve observations, received reports and interventions important to reconstructing atrocities. Eyewitness passages, hearsay and estimates require distinction, and his location did not cover every area. Comparison with Vautrin, Safety Zone documents, Japanese records and trials strengthens reconstruction.\n\nHis efforts to communicate after returning to Germany occurred within that regime’s constraints. Commending his civilian protection does not turn the Nazi system into a humanitarian institution or eliminate the need to examine his political identity.', ['nanjing-archive', 'vautrin-diary', 'nara-japan']),
  ],
  'minnie-vautrin': [
    d('金陵女子文理学院与女性避难', 'Ginling College and refuge for women',
      '魏特琳长期从事教育，南京陷落后在金陵女子文理学院组织保护妇女和儿童。校园空间、外国人身份及反复交涉构成有限庇护，性暴力威胁却持续存在。救助不能只按登记人数评价，还应考察食物、拥挤、卫生和被迫带走的风险。\n\n她与中国同事及避难者共同维持日常生活，女性既是受害者也是照护、组织和自救者。将其工作纳入战争史，有助把关注从战役地图扩展到身体安全与学校、家庭怎样在占领中存续。',
      'An educator, Vautrin organized refuge for women and children at Ginling College after Nanjing fell. Campus space, foreign status and repeated intervention offered limited shelter under continuing threats of sexual violence. Registrations alone cannot measure safety, food or sanitation.\n\nChinese colleagues and refugees helped sustain daily life. Women acted as caregivers and organizers as well as victims. Their experience connects military history to bodily security and the survival of schools and households under occupation.', ['vautrin-diary', 'nanjing-archive']),
    d('持续创伤与见证记录', 'Enduring trauma and testimony',
      '魏特琳的日记以连续日期呈现暴力、交涉与救助压力，能够让读者看到南京暴行并非城市陷落当日即结束。她后来严重的心理痛苦和1941年自杀，提醒研究者救援者也承受长期创伤；不能在缺少临床资料时替她作出完整现代诊断。\n\n传记不应将苦难写成必须自我牺牲的道德标准。保存其观察与中国幸存者经验，同时说明资料遗漏，有助承认救助的价值和无法阻止的伤害，而不是用一个感人故事代替暴行调查。',
      'Her dated diaries show violence and the strain of intervention continuing beyond the city’s fall. Her later distress and death by suicide in 1941 also reveal the burden on rescuers, without authorizing a complete retrospective clinical diagnosis.\n\nBiography should not make self-sacrifice a required moral standard. Preserving her observations together with Chinese survivors’ experiences recognizes both valuable protection and harms that protection could not prevent.', ['vautrin-diary', 'nanjing-archive']),
  ],
  'mao-zedong': [
    d('革命领导权的形成与战时治理', 'Revolutionary leadership and wartime government',
      '毛的农村革命道路在军事失败、地方社会冲突和党内争论中逐步形成，并非1921年已具备后来全部路线。根据地土地政策、军队纪律和干部组织帮助扩大动员，也伴随阶级划分、征收与内部清洗。长征及西北落脚使组织保存，抗战和延安整风进一步集中领导权。\n\n他在持久战论述中分析敌强我弱与战争阶段，中共实际军事和社会行动则需依各根据地考察。整风提高组织一致性，同时压缩思想与人身保障，不能只把学习制度或错误清查中的一面作为全部。',
      'Mao’s rural strategy developed through defeat, social conflict and party debate rather than existing fully formed in 1921. Land policy, discipline and cadres expanded mobilization alongside coercive classification and internal purges. The Long March, northwestern base and wartime rectification consolidated leadership.\n\nHis theory of protracted war analyzed unequal strength and stages, while actual Communist activity varied by base area. Rectification improved organizational unity and also weakened intellectual and personal safeguards; both processes require examination.', ['mao-early', 'mao-peasants', 'long-march', 'rectification-study', 'resistance-war']),
    d('建国后发展、灾难与最高责任', 'Development, catastrophe and supreme responsibility',
      '建国后的国家整合、工业、教育和公共卫生发展，与毛的政治动员及其他组织、劳动者投入共同相关。大跃进把高目标、公社化和政治竞争结合，粮食征购、虚报与限制纠错加重饥荒。庐山会议打击批评及后来文革发动，显示最高权力能够把路线争议转化为大规模迫害。\n\n承认地方差异与其他干部行为，不削弱毛在发动、维持和阻止纠正中的主要责任。中美接近又说明外交能够务实调整，与国内激进政治同时存在。评价必须追踪不同政策及受影响群体，而非用最后一个功过比例结清生命损失和制度遗产。',
      'State integration and gains in industry, education and health combined Mao’s mobilization with institutions and collective labor. Great Leap targets, communes, procurement, inflated reports and suppressed correction intensified famine. Lushan and the Cultural Revolution show how supreme authority converted policy disagreement into persecution.\n\nLocal variation and other officials’ actions do not erase his principal responsibility for initiating, maintaining or obstructing correction of harmful policies. Rapprochement with the United States also coexisted with domestic radicalism. These different processes cannot be settled through a single score of achievement against loss.', ['resolution-1981', 'famine-institutions', 'cultural-revolution-impact', 'rapprochement-frus']),
  ],
  'zhou-enlai': [
    d('革命网络到国家行政', 'From revolutionary networks to state administration',
      '周恩来的革命经历连接旅欧组织、黄埔政治工作、地下活动和军事协调，长期优势在于组织联络及谈判。抗战中与国民政府及外国人士接触，建国后担任总理，负责部门间协调和外交，使个人影响与国家行政系统紧密相连。\n\n外交中的万隆和中美接近不能仅作为个人风度展示，背后是中国安全、经济条件与国际联盟的调整。交涉成果也需要其他外交官、技术人员与最高决策配合，个人能力解释部分过程，却不替代政策利益。',
      'Zhou’s career connected European revolutionary networks, Whampoa political work, underground organization and military coordination. Wartime contacts and his long premiership made liaison and administrative negotiation central to his influence.\n\nBandung and rapprochement with the United States concerned security and international alignments as well as diplomatic skill. Results depended on other officials, specialists and supreme decisions; personal manner explains only part of policy.', ['rectification-study', 'resolution-1981', 'rapprochement-frus']),
    d('政治运动中的保护与参与', 'Protection and participation in political campaigns',
      '周在政治运动中保护某些干部、专家和文化人员的行动有必要记录，但保护范围受到毛的权威及本人政治选择限制。他也参与中央路线的组织与执行，不能把所有伤害归给激进派而将总理行政完全放在制度之外。\n\n个人私下同情、公开表态、签署文件和实际阻止伤害是不同层次的证据。研究应具体询问谁得到保护、谁未得到、当时权限为何，而不以温和形象直接证明没有责任。1976年的悼念又包含公众对政治处境的表达，超出对生前每项政策的一致认可。',
      'Zhou’s protection of some officials and specialists deserves documentation, within limits imposed by Mao’s authority and his own choices. He also organized and implemented central policies. The premiership cannot be placed wholly outside the system that produced harm.\n\nPrivate sympathy, public statements, signed decisions and effective intervention are different evidence. Who received protection and what authority was available matter more than a benign image. Mourning in 1976 expressed wider political concerns rather than unanimous endorsement of every policy.', ['resolution-1981', 'cultural-revolution-impact', 'rectification-study']),
  ],
  'peng-dehuai': [
    d('指挥者的战略与战争成本', 'Command decisions and the costs of war',
      '彭德怀从红军组织进入长期军事领导，百团大战和朝鲜战争是其生涯的重要阶段。抗战中的大规模进攻打击交通与据点，也引发对暴露兵力及随后报复的讨论；日本报复责任不能因此转嫁给抗日者，但指挥者对居民风险和军事收益仍须评估。\n\n入朝作战涉及中央决策、前线补给、严寒和敌方火力，不能只以某次胜负评价全局。战争成本包括军人伤亡、朝鲜平民及国内资源投入，军事能力与政治决策责任需要相接而不混同。',
      'The Hundred Regiments Offensive and Korean War were major stages of Peng’s command career. Attacks on transport and strongpoints raised questions about force exposure and subsequent retaliation. Japanese responsibility for reprisals remains distinct from commanders’ obligations to consider civilian risk.\n\nIn Korea, central decisions, logistics, cold and enemy fire shaped operations. Military casualties, Korean civilians and domestic resources belong to the cost of war. Command ability and political responsibility connect without becoming identical.', ['resistance-war', 'korea-history', 'resolution-1981']),
    d('庐山批评与被迫害的过程', 'Lushan criticism and persecution',
      '1959年彭向毛写信反映大跃进问题，并非提出完整替代政权方案。毛把批评上升为路线斗争，彭遭撤职及持续批判，党内纠错空间收缩。将其失败只解释为脾气耿直，会遗漏最高权力和组织惩罚机制。\n\n文革中的进一步迫害使他健康恶化，1974年去世，后来获平反。平反能够纠正官方定性，却不能归还失去的生命和政策纠错机会。他的受害经历也不应使研究停止审视此前军队及运动中的具体行为。',
      'Peng’s 1959 letter reported Great Leap problems rather than presenting a complete alternative regime. Mao turned criticism into a line struggle; removal and continuing denunciation narrowed corrective space. Personality alone cannot explain this mechanism of power and punishment.\n\nFurther Cultural Revolution persecution preceded his death in 1974 and later rehabilitation. Reversal of official judgment could not restore his life or lost opportunities for correction, nor does victimhood place all earlier actions beyond investigation.', ['resolution-1981', 'famine-institutions', 'cultural-revolution-impact']),
  ],
  'liu-shaoqi': [
    d('组织纪律与国家经济调整', 'Organizational discipline and economic adjustment',
      '刘少奇的领导基础来自工运、地下组织与党内干部制度，重视组织纪律和修养。土地改革和社会主义改造中，他与毛长期共同推动制度转换，二者并非从一开始就分别代表改革与激进两条固定路线。政策执行中的分类、暴力和权利损失应记录其参与层次。\n\n大饥荒后，刘参与调查、经济调整及恢复生产，干部对危机的认识逐步变化。承认后来的纠偏，不等于抹去此前支持与责任；也不能把当时具体措施直接等同于1978年后的市场改革。',
      'Liu’s authority grew from labor organizing, underground work and cadre institutions. He and Mao long cooperated in land reform and socialist transformation rather than representing two fixed opposing lines from the beginning. Classification and coercion require attention to his actual participation.\n\nAfter famine he joined investigations and economic adjustment. Later correction does not erase earlier support, and these measures were not identical to post-1978 market reform.', ['land-mao-liu', 'resolution-1981', 'famine-institutions']),
    d('国家主席身份为何未能保护本人', 'Why the presidency did not protect him',
      '文革中刘被指为党内主要敌人，正式国家职务未能提供独立法律保障。党内定性、群众动员和控制医疗共同造成其失去自由及健康，1969年在迫害中死亡。这一过程不仅是领导人之间私人冲突，也是法律和行政从属于政治运动的体现。\n\n1980年平反改变官方历史叙述，家属与受害者经历仍不能只由一项决议代表。其生涯使研究同时面对施政参与者和受害者两种身份，制度分析应解释身份如何转换，而非要求人物始终只有正面或负面一个位置。',
      'During the Cultural Revolution, political designation as a principal enemy overrode Liu’s formal presidency. Denunciation, confinement and denial of proper medical care preceded his death in persecution in 1969. This exposed the subordination of legal safeguards to political campaigns.\n\nRehabilitation in 1980 changed the official judgment without representing every family experience. His career connects participation in government with subsequent victimhood; explaining that transformation is more useful than assigning one permanent moral identity.', ['resolution-1981', 'cultural-revolution-impact']),
  ],
  'deng-xiaoping': [
    d('革命干部到改革联盟', 'From revolutionary official to reform coalition',
      '邓的政治力量来自战争和组织经验、与军队及老干部的关系，并非只依赖一个正式国家职位。反右中的参与和文革中两次失势都属于其经历，后来改革不应使前者消失。复出后恢复教育、支持农村试验、特区与对外开放，依靠地方实践及陈云等不同立场领导人的合作竞争。\n\n改革不是一天宣布完成的完整蓝图，价格、产权、财政和就业逐步变化。邓为试验提供政治支持，也在通胀与秩序问题上设置边界，经济务实不能自动理解为所有领域的自由化。',
      'Deng’s power rested on revolutionary experience, military ties and senior networks beyond any single state office. Participation in the Anti-Rightist Campaign and Cultural Revolution purges both belong to his biography. Reform combined his support with local experiments and cooperation or conflict among other leaders.\n\nEducation, rural incentives, special zones and opening developed through successive changes rather than one finished blueprint. Pragmatism in economic policy did not imply liberalization across all political fields.', ['resolution-1981', 'reform-steps', 'reform-development']),
    d('1989年决定与1992年再推动', 'The 1989 decision and renewed reform in 1992',
      '1989年，邓支持戒严和以军队解决政治危机，虽不任党总书记或国家主席，仍具有最高实际决定权。责任不能因正式职位不同而落空，也不能只用稳定或增长的后来结果合理化当时对平民的武力。赵紫阳、李鹏和军队执行层应分别说明。\n\n1992年南方谈话重新推动市场取向，为增长和制度转变打开空间，同时延续一党统治框架。改革推进与镇压责任并存并不构成事实矛盾；把两者拆开后分别研究，才能看到同一领导人的发展目标与权力观如何相连。',
      'In 1989 Deng supported martial law and military resolution despite holding neither the party general secretaryship nor state presidency. His effective supreme authority remains central to responsibility, alongside distinct roles of Zhao, Li Peng and military executors. Later growth cannot retroactively justify civilian harm.\n\nThe 1992 southern tour renewed market-oriented reform within one-party rule. Economic transformation and repression are coexisting parts of his record, connected by his views of development, order and political authority.', ['tiananmen-decision', 'tiananmen-documents', 'reform-steps']),
  ],
  'hu-yaobang': [
    d('平反、干部工作与改革边界', 'Rehabilitation, cadre policy and reform limits',
      '胡耀邦在文革后主持组织工作和进入中央领导，推动大量错案纠正、知识分子恢复工作及干部年轻化。平反不仅是改变政治称号，还涉及职业、家庭、工资和教育机会；其作用应按实际恢复程度检验。改革形象因此有具体制度实践基础。\n\n他仍在一党领导内行动，与邓及其他老干部存在权力层级和路线约束。较宽容作风不表示已经提出或实施完整多党制度，不能把后来公众愿望全部放进其生前计划。',
      'Hu promoted rehabilitation, restoration of intellectuals’ work and cadre renewal after the Cultural Revolution. Reversal of political labels affected employment, households, wages and education, with results depending on actual restitution. His reform reputation therefore has institutional foundations.\n\nHe nevertheless acted within one-party leadership and senior constraints. A more tolerant style does not establish that a complete multiparty system was proposed or implemented, or that later public hopes were his own program.', ['resolution-1981', 'reform-development', 'tiananmen-decision']),
    d('去职、去世与悼念政治', 'Removal, death and the politics of mourning',
      '1987年胡因学生运动和反自由化争议辞去总书记，显示改革期最高党职也受元老权威制约。1989年4月去世后的悼念成为表达反腐、新闻自由和政治参与诉求的契机，学生、工人及居民并非只为同一人物生平而行动。\n\n胡已在抗议扩展、戒严及六月镇压前去世，因此不能将后续决策记在其名下。纪念中的正面形象能够反映公众不满，但仍需与生前具体政策区分，让历史人物与借其表达的政治希望各自保持真实。',
      'Hu’s resignation in 1987 amid disputes over student protest and liberalization showed the limits of the formal general secretaryship under senior authority. Mourning after his April 1989 death became a setting for demands about corruption, media and participation.\n\nHe died before martial law and the June crackdown and cannot be assigned those decisions. Public memory reveals contemporary aspirations as well as his reputation; it should remain distinct from his documented lifetime policies.', ['tiananmen-us', 'tiananmen-decision', 'resolution-1981']),
  ],
  'zhao-ziyang': [
    d('农村经验与城市改革的难题', 'Rural experience and urban reform problems',
      '赵紫阳在四川支持恢复生产激励及农村改革，地方经验帮助其进入中央经济领导。任总理后面临计划与市场并存、企业约束和价格失衡，改革可以提高效率，也产生寻租、通胀与收入差异。1988年价格改革争议表明政策设计、公众预期和执行次序缺一不可。\n\n其政治改革讨论涉及党政关系和行政效率，不能直接等同全面民主化已经启动。早期参与政治运动与后来主张对话属于不同阶段，生涯变化需要解释，不能只从1989年的结局反推此前一直持相同立场。',
      'Zhao’s support for production incentives and rural reform in Sichuan helped bring him to central economic leadership. Dual planning and markets created efficiency gains alongside rent-seeking, inflation and unequal incomes. The 1988 price controversy exposed problems of design, expectations and sequencing.\n\nHis political-reform discussions concerned party-government relations and administration without establishing completed democratization. Earlier campaign participation and later support for dialogue reflect a changing career rather than one unvarying position.', ['reform-development', 'reform-steps', 'tiananmen-decision']),
    d('反对军事解决与长期失去自由', 'Opposition to military resolution and confinement',
      '1989年赵与邓及强硬领导人产生决定性分歧，主张通过对话处理抗议并反对戒严路线。他赴广场讲话具有公开政治意义，但个人劝说不能代替已转向军事处置的组织权力。失去总书记职位后长期被限制自由，直到2005年去世。\n\n晚年录音和回忆为高层决策提供稀缺内部视角，也含事后解释和本人立场。把它与外交电报、同期讲话及其他记录比较，可以辨认哪些细节得到互证。承认其拒绝镇压的选择，不要求把所有经济政策及早期行为都写成没有问题。',
      'In 1989 Zhao broke with Deng and hard-line leaders over dialogue and martial law. His square visit had public significance, but persuasion could not replace authority already shifting toward military action. Removal was followed by prolonged restrictions until his death in 2005.\n\nLater recordings offer a rare internal account with retrospective judgments and personal interests. Comparison with contemporary speeches and diplomatic records is necessary. Recognizing his opposition to repression does not require endorsing every earlier policy.', ['tiananmen-decision', 'tiananmen-documents', 'tiananmen-us']),
  ],
  'jiang-zemin': [
    d('危机后的接班与市场化', 'Succession after crisis and market transformation',
      '江泽民1989年从上海进入中央最高领导，权力巩固依靠元老支持、组织调整和此后军政关系。社会主义市场经济、财税与国企改革及加入WTO在其任期推进，朱镕基、地方政府、企业和劳动者也有各自作用，不能把增长全部归于总书记个人。\n\n改革扩大机会也集中造成下岗、福利重组和地区差异。三个代表将私营企业家等纳入党的政治代表论述，反映党适应市场社会的尝试，而不意味着独立政治竞争已经开放。',
      'Jiang’s 1989 elevation from Shanghai depended on senior support and subsequent organizational and military consolidation. Market transformation, fiscal and enterprise reform and WTO accession involved Zhu Rongji, local governments, firms and workers as well as his leadership.\n\nNew opportunities accompanied concentrated layoffs and welfare restructuring. The Three Represents accommodated changing social groups within party representation, rather than opening independent political competition.', ['reform-steps', 'reform-development', 'wto-accession']),
    d('国际融入与国内控制', 'International integration and domestic control',
      '香港、澳门移交及全球贸易联系扩大了国家外交空间，党国同时维持新闻、组织和政治活动限制。1999年后针对法轮功的压制涉及中央决定、专门治理及地方执行，对拘禁和虐待的报告需明确来源与核查条件，不能因团体信仰争议而取消成员权利。\n\n退休后影响及网络怀旧是另一个历史层次。公众对后来的比较可能改变江的形象，但不能据此反改当时政策。开放贸易、文化变化和强制政治控制能够并行，应分别检验受益者、受害者及具体机制。',
      'Hong Kong and Macao handovers and global trade expanded diplomatic connections while restrictions on media and organization persisted. The post-1999 suppression of Falun Gong involved central policy and local enforcement. Reports of detention and abuse require clear attribution; disputed beliefs do not remove members’ rights.\n\nLater influence and online nostalgia belong to a separate history of memory. Comparison with subsequent leaders should not rewrite his contemporary record of international opening and coercive domestic control.', ['wto-accession', 'falungong-study', 'macau-declaration', 'taiwan-republic']),
  ],
  'zhu-rongji': [
    d('任期与2026年逝世', 'Terms of office and death in 2026',
      '朱镕基1991年进入国务院担任副总理，1998—2003年任总理，退休后仍是公众讨论改革时代的重要人物。官方讣告记载其于2026年8月12日在北京逝世，本传因此将生卒年更新为1928—2026，而不继续标为在世。\n\n讣告能够核对日期和任职，但其中高度赞誉是发布机构的评价。理解其施政仍需结合改革研究、经济资料及受影响家庭，不能把死亡报道当作对所有历史争议的最终裁定。',
      'Zhu became vice premier in 1991 and served as premier from 1998 to 2003. An official notice records his death in Beijing on 12 August 2026; this biography therefore updates his dates to 1928–2026.\n\nThe obituary establishes dates and appointments, while its praise remains the issuing institutions’ judgment. Policy assessment also requires economic research and affected households’ experiences rather than treating a death notice as a final verdict on historical disputes.', ['zhu-obituary-2026', 'reform-development']),
    d('宏观稳定与制度改造', 'Macroeconomic stabilization and institutional change',
      '朱镕基从上海经济治理进入中央，在通胀、银行坏账和国企亏损背景下推动整顿。1994年分税制改变中央地方收入关系，金融与企业改革尝试强化预算和经营约束，住房制度转变又重塑居民资产与城市发展。各措施目标与成本不同，不宜统称一次简单市场放开。\n\n加入WTO需要国际谈判及国内规则调整，承诺与实际执行要分别核对。办事强硬的公众形象能解释政策风格，不能单独证明每项行政措施公平或有效。',
      'Zhu’s move from Shanghai to central administration coincided with inflation, banking risk and enterprise losses. Tax sharing, financial restructuring, enterprise constraints and housing reform changed different institutions, with distinct aims and costs rather than one simple market opening.\n\nWTO accession required negotiation and domestic rule changes, whose commitments and implementation need separate assessment. A forceful public image explains style without proving the fairness or effectiveness of every measure.', ['reform-development', 'reform-steps', 'housing-1998', 'wto-accession']),
    d('效率目标与转型家庭', 'Efficiency objectives and households in transition',
      '国企重组使部分企业提高效率，也让下岗者失去工作、单位住房和医疗保障的稳定来源。买断工龄、再就业与社会保险在不同地方执行不一，不能用全国增长率替代家庭经历。朱作为经济行政主要领导承担政策责任，地方管理和企业行为仍须分别分析。\n\n财政集中提高中央调控能力，也与地方支出责任、土地收入和后来债务问题发生联系；不能把多年后所有结果倒写成改革当时必然预见。评价应比较可行替代、过渡支持和权利程序，让制度收益与分布不均的代价同样可见。',
      'Enterprise restructuring improved some firms while displaced workers lost stable employment and work-unit welfare. Local differences in compensation, reemployment and insurance matter more to households than a national growth figure alone. Zhu’s policy responsibility coexisted with local and enterprise decisions.\n\nCentral revenue capacity interacted with local spending obligations, land revenue and later debt. Subsequent outcomes should not all be treated as foreseen inevitabilities. Alternatives, transitional support and rights procedures help assess both gains and unequal costs.', ['reform-development', 'reform-steps', 'housing-1998']),
  ],
  'xi-jinping': [
    d('领导集中、组织与政策范围', 'Concentrated leadership and policy reach',
      '习近平从地方到中央的任职经历能够以官方履历核对，但任期表现需另看政策和结果。2012年后反腐与机构改革改变干部激励及权力结构，国家监察和党对各领域领导强化，2018年取消国家主席连续任职限制。党总书记、国家主席和军委主席具有不同制度来源，不能把任期规则混为同一条。\n\n扶贫、科技、军队和绿色转型体现长期国家目标，成效依赖此前积累、地方执行及居民劳动。集中领导可能加快资源动员，也压缩公开异议和独立监督，效率与纠错应按实际过程检验。',
      'Official records establish Xi’s appointments; performance requires separate evidence. Anti-corruption, institutional restructuring and expanded party leadership changed incentives and authority. The 2018 removal of consecutive presidential term limits concerned a state office, distinct from party and military positions.\n\nPoverty reduction, technology, military change and green transition draw on prior investment and local labor. Concentration can accelerate mobilization while restricting dissent and independent oversight. Claims about efficiency and correction need observable policy processes.', ['xi-biography', 'amendment-2018', 'poverty-report', 'constitution']),
    d('安全治理、国际压力与未完任期', 'Security governance, external pressure and an unfinished tenure',
      '新疆治理、香港国安制度及新冠应对显示安全目标进入不同生活领域。联合国人权高专办对新疆的评估与中国政府反驳应各自准确呈现，不能把评估写成法院判决，也不能因反驳存在便取消其调查所据。疫情从严格防控到2022年末调整，须分别记录健康收益、限制成本和转段准备。\n\n截至2026年10月资料截点，任期仍在进行，经济预测、规划和外交主张均不等于已发生结果。评价需要持续保留就业、人口、债务及国际关系的不确定性，不按未来成败为当下政策预先盖章。',
      'Xinjiang policy, Hong Kong national-security arrangements and COVID governance extended security objectives into different spheres. The OHCHR assessment and China’s response require accurate attribution: an assessment is not a court judgment, and a rebuttal does not erase its evidence.\n\nStrict containment and the late-2022 transition require distinct accounts of health benefits, restrictions and preparation. At the October 2026 cutoff, the tenure continues. Forecasts and plans are not realized outcomes; employment, demographics, debt and external relations retain uncertainty.', ['xinjiang-ohchr', 'xinjiang-response', 'hongkong-policy-2020', 'who-china-2023', 'wb-2026']),
  ],
  'qian-xuesen': [
    d('跨国科学训练与回国组织', 'Transnational scientific training and organization',
      '钱学森在美国的航空、力学和火箭研究使其拥有理论与工程组织经验，冷战安全审查和限制离境又将科学职业卷入政治。1955年回国后参与导弹航天体系建设，技术路线、人才培养和跨部门组织成为贡献的重要部分。\n\n个人作用应放在大型团队与国家投入中理解，设计、试验、生产、测量和维护都需要许多人。把航天写成一个天才独自完成，会使工程失败、制度学习和普通技术劳动不可见，也难以解释系统为何能够持续运行。',
      'Qian’s American work in aeronautics, mechanics and rocketry provided theoretical and organizational experience. Cold War security restrictions politicized his career. After returning in 1955, he helped develop missile and space institutions, technical direction and training.\n\nLarge teams and public investment supported design, testing, production and maintenance. A lone-genius narrative obscures technical labor, failures and organizational learning necessary to explain a durable engineering system.', ['qian-biography', 'third-front']),
    d('科学贡献与公共判断的区别', 'Scientific achievement and public judgment',
      '科学家具有专业成就不意味着其对农业、政治或社会的所有判断都同样可靠。评价钱学森需要把可验证的理论工程工作与公共表态分开，避免用权威代替证据，也不应因某类判断有争议便否认全部专业贡献。\n\n国防研究的保密使公众能看到的资料有限，不能以公开纪念文章推定每项未公开技术细节。系统工程提供协调复杂工作的思路，但社会目标、权利与分配不是仅靠技术最优化就能决定的问题，科学组织史须保留这些边界。',
      'Professional achievement does not make every judgment about agriculture, politics or society equally reliable. Verifiable engineering work and public statements deserve separate assessment, without either authority replacing evidence or controversy cancelling all contribution.\n\nDefense secrecy limits accessible technical records. Commemorative accounts cannot establish undisclosed details. Systems engineering aids coordination, but social aims, rights and distribution also require political and ethical judgment beyond technical optimization.', ['qian-biography', 'third-front', 'famine-institutions']),
  ],
  'tu-youyou': [
    d('523项目中的实验路径', 'Experimental work within Project 523',
      '屠呦呦的青蒿素研究在疟疾治疗需求、国家科研组织和传统医药资料相遇的环境中展开。她与团队从方药信息、提取方法和实验观察逐步获得有效线索，低温提取的思路需要通过实验检验，不能仅以古籍出现植物名称便说现代药物已经完成。\n\n523项目是多单位合作，提取、结构、临床和生产环节贡献不同。2015年诺贝尔奖肯定其关键发现，不表示其他研究者没有贡献，也不应把个人获奖误当整个药物应用体系只由一人创造。',
      'Tu’s artemisinin research combined the need for malaria treatment, organized research and traditional medical texts. Extraction methods and laboratory observation tested leads; an ancient reference to a plant was not itself a finished modern drug.\n\nProject 523 involved multiple institutions and distinct work in extraction, structure, trials and production. The 2015 Nobel Prize recognized Tu’s crucial discovery without erasing colleagues’ contributions or attributing the entire treatment system to one person.', ['tu-biography']),
    d('从发现到公共健康', 'From discovery to public health',
      '药物发现与可及治疗之间还有质量控制、剂量、安全性、联合疗法和耐药监测等环节。青蒿素的历史说明传统知识可以提供线索，现代证据则决定疗效和风险；它既不支持把传统经验全部否定，也不支持未经试验便推广所有传统处方。\n\n传记应记录女性科学家在集体项目中的可见性与贡献归属，同时避免把奖励迟到简单写成一种单一原因。研究制度、署名习惯、保密和国际传播共同影响认可过程，具体个人遭遇仍需档案与本人材料支持。',
      'Discovery still requires quality control, dosing, safety evidence, combination treatment and resistance monitoring before accessible care. Traditional knowledge can supply leads while modern testing establishes benefits and risks; this history supports neither blanket rejection nor untested endorsement.\n\nRecognition also raises questions about women’s visibility and credit within collective projects. Research institutions, authorship practices, secrecy and international communication affected acknowledgment. Particular experiences require records rather than a single assumed explanation.', ['tu-biography']),
  ],
  'tsai-ing-wen': [
    d('选举授权与治理争议', 'Electoral mandates and governing disputes',
      '蔡英文的政治生涯连接法律、贸易行政与民进党组织，2016年及2020年当选总统，2024年任期结束。选举授权提供民主合法性，不使劳工、能源、住房和司法政策免于检验。政府、立法院、地方及社会运动具有各自权力，不能只把所有成果或问题归于总统个人。\n\n转型正义与二二八记忆进入公共政策，涉及档案开放、赔偿和威权象征处理。不同受害者和政治群体对执行范围可能存在争议，程序公开与证据标准应独立于政党支持，避免以一次表态替代长期修复。',
      'Tsai’s career combined law, trade administration and party leadership. Elected in 2016 and 2020, she completed her presidency in 2024. Democratic mandates did not remove scrutiny of labor, energy, housing or justice policies, whose outcomes involved other institutions.\n\nTransitional justice addressed archives, compensation and authoritarian symbols. Victims and political groups could disagree on implementation; public procedures and evidence standards matter independently of partisan allegiance.', ['taiwan-tsai', 'taiwan-elections', '228-truth']),
    d('两岸政策与继任之后', 'Cross-strait policy and the end of her presidency',
      '蔡任内强调维持现状和台湾民主制度，北京则以一中原则及反独立立场施压。双方对政治前提和主权解释不同，军演、外交空间及美国联系共同改变安全环境。描述各方主张不等于承认其为所有居民一致同意，民意需注明调查日期与问题。\n\n2024年赖清德接任后，不能把其任期政策继续记为蔡的总统决定。她的遗产可以追踪军备、社会政策及制度信任的持续影响，尚在发生的结果则保留未定，避免把历史人物页面变成固定竞选评价。',
      'Tsai emphasized the status quo and Taiwan’s democratic institutions, while Beijing asserted its one-China position and opposition to independence. Military activity, diplomatic constraints and American ties shaped security. Stating government positions does not establish unanimous public agreement.\n\nAfter Lai Ching-te succeeded her in 2024, his decisions should not be assigned to her presidency. Continuing effects on defense, social policy and institutional trust can be studied without presenting unfinished outcomes as settled legacy.', ['taiwan-tsai', 'taiwan-inauguration', 'taiwan-whitepaper-2022']),
  ],
  'hirohito': [
    d('帝国最高象征与实际决策', 'Imperial authority and actual decisions',
      '裕仁在日本帝国制度中拥有最高象征和宪制地位，军队以天皇名义行动。实际决策又经过内阁、统帅机关和军方，不能把制度形式直接当作每项战地命令由本人制定。关于其知情、批准和干预，应依据具体会议、奏报及研究逐项判断。\n\n同样，官僚与军队分工不意味着天皇完全没有能动性。侵华战争扩张与国家资源动员在其统治下持续，责任分析应考察可用权威和实际选择，而非只在全能独裁者与无权象征之间二选一。',
      'Hirohito held supreme symbolic and constitutional standing, and armed forces acted in the emperor’s name. Cabinets and military commands also made decisions, so formal authority does not prove authorship of each battlefield order. Knowledge, approval and intervention require specific records.\n\nInstitutional division likewise does not establish complete powerlessness. War expansion and mobilization continued under his reign. Available authority and actual choices provide a better basis for responsibility than either omnipotence or a purely passive symbol.', ['hirohito-authority', 'nara-japan', 'resistance-war']),
    d('投降、免于起诉与战后记忆', 'Surrender, non-prosecution and postwar memory',
      '1945年接受投降的决定中，天皇干预具有重要作用，但不能以最后止战行为抹去此前战争。战后美国占领当局保留天皇并使其免于东京审判起诉，政治稳定及占领政策影响此安排；未被起诉不等于历史上已证明完全无责任。\n\n战后象征天皇身份与战时制度不同，后来的和平形象还受国家记忆和外交影响。分析应把法律审判、政治处理与历史责任分开，既准确说明起诉范围，也保留对最高统治者战争角色的研究空间。',
      'Imperial intervention mattered in accepting surrender in 1945 without cancelling responsibility for preceding war. American occupation policy retained the emperor and excluded him from prosecution at Tokyo. Political stabilization shaped this choice; non-prosecution did not establish historical innocence.\n\nThe postwar symbolic office differed from the wartime system. Legal judgment, occupation policy and historical responsibility should remain distinct, preserving inquiry into his actual role while accurately stating the limits of prosecution.', ['nara-japan', 'potsdam', 'hirohito-authority', 'frus-hirohito-1946']),
  ],
  'joseph-stalin': [
    d('对华政策的国家利益与革命关系', 'State interests and revolutionary ties with China',
      '斯大林对华政策并非始终无条件支持中共，苏联国家安全、对日战争、大国协议及与国民政府关系同时影响选择。1945年出兵东北和战后撤军改变地区军事条件，对中共扩展机会具有影响，却不能把中国革命胜利完全解释为外部赠予。\n\n1950年中苏条约及援助支持新中国安全和工业建设，也包含利益谈判与不对称。毛与斯大林之间既有意识形态联结，也有国家主权和战略分歧，不能以同志称呼推定全部目标一致。',
      'Stalin’s China policy balanced Soviet security, the war against Japan, great-power agreements and relations with the Nationalist government. The 1945 intervention and withdrawal from Manchuria changed military opportunities without making Communist victory simply an external gift.\n\nThe 1950 treaty and assistance supported PRC security and industry through asymmetric negotiation. Ideological ties coexisted with sovereignty and strategic differences; shared Communist identity did not guarantee identical interests.', ['stalin-authority', 'sino-soviet', 'civilwar-study']),
    d('朝鲜战争与1953年后的遗产', 'The Korean War and the legacy after 1953',
      '朝鲜战争前后，斯大林、金日成和毛之间的决策与风险承担不同。苏联支持朝鲜并提供军事资源，中国投入地面部队，不能将三方视为一个没有分歧的行动者。战争始于朝鲜军队向南进攻，随后联合国军与中国介入形成更广冲突。\n\n1953年斯大林去世改变联盟政治，后来的去斯大林化又成为中苏争论的重要背景，但分裂并非一场讲话直接造成。人物生平在1953年结束，影响继续存在，必须区分本人决定与继任者以其遗产开展的政治。',
      'Stalin, Kim Il-sung and Mao made different decisions and bore different risks in Korea. Soviet support and Chinese ground intervention should not be treated as one undivided action. North Korea’s southward invasion preceded the wider UN and Chinese involvement.\n\nHis death in 1953 and later de-Stalinization changed alliance politics. The Sino-Soviet split had further causes beyond one speech. Biography ends his own decisions at death while tracing later uses of his legacy separately.', ['korea-history', 'un-korea-82', 'sino-soviet', 'stalin-authority']),
  ],
  'song-qingling': [
    d('革命继承与同蒋决裂', 'Revolutionary inheritance and rupture with Chiang',
      '宋庆龄与孙中山的婚姻连接革命核心，但其政治活动具有独立判断。1927年后她反对国民党清共和蒋的路线，维持与左翼及共产党人的合作。家族中不同成员走向不同政治阵营，说明亲属网络并不自动产生一致政策。\n\n抗战救济、儿童福利和海外联系扩展其公共角色，不能只作为孙的遗孀描述。她对革命正统的理解与后来党国秩序之间仍需具体比较，象征地位不等于每项政策都有直接行政权限。',
      'Marriage to Sun connected Soong Ching-ling to revolutionary leadership, but she made independent political choices. Opposition to the 1927 purges and Chiang’s line sustained cooperation with the left and Communists. Family connections did not produce uniform political allegiance.\n\nWar relief, child welfare and international contacts extended her public role beyond widowhood. Revolutionary symbolism and direct administrative authority remain distinct when assessing her later position.', ['republic-sources', 'split-1927', 'resistance-war']),
    d('新中国的象征、福利与责任边界', 'Symbolism, welfare and limits of authority in the PRC',
      '1949年后宋庆龄担任国家领导职务，参与妇女儿童与国际友好事业，其经历帮助新政权呈现超越共产党成员的革命联盟。此代表性有政治意义，但不能据国家副主席等称谓推定她实际指挥全部政治运动。\n\n对其在危机中的保护、沉默或表态应查具体记录，而不能仅以善意形象免除讨论，也不应把其他领导的决定直接记为她个人行为。福利工作可以改善特定群体生活，同时仍处于缺少独立监督的政治环境，两层事实都需要保留。',
      'After 1949, Soong held state offices and worked in welfare and international friendship, symbolizing a revolutionary coalition extending beyond Communist membership. Such representation did not confer command over every campaign.\n\nProtection, silence and statements during crises require particular records. Welfare could improve lives within a political system lacking independent oversight. Neither a benevolent image nor an official title establishes the full extent of personal responsibility.', ['resolution-1981', 'republic-sources', 'resistance-war']),
  ],
  'cai-yuanpei': [
    d('大学制度与思想空间', 'University institutions and intellectual space',
      '蔡元培的教育实践将大学理解为研究与思想交流的场所，北大任用不同立场学者，扩大新文化讨论空间。兼容并包不能理解为校园始终没有权力冲突，课程、经费、学生政治与外部压力都影响实际自由。\n\n五四期间对学生的支持和斡旋使大学进入全国政治，学术自主与救亡动员并不总能协调。大学转型依靠教师、学生和行政共同劳动，校长理念有作用，却不能替代对具体制度及参与者处境的考察。',
      'Cai promoted universities as places of research and intellectual exchange. Appointing scholars with differing views broadened debate at Peking University without removing conflicts over curriculum, finance or politics.\n\nDuring May Fourth, support for students and negotiation connected university life to national mobilization. Academic autonomy and political urgency could conflict. Institutional change depended on teachers, students and administrators as well as a president’s ideas.', ['republic-sources', 'mayfourth-archives', 'chen-awakening']),
    d('教育改革者的政治参与', 'An educational reformer’s political participation',
      '蔡并非只在政治之外保护学术，也参与国民党政治及1927年前后的组织事务。其与清共背景的关系需要明确记录，不能因为教育贡献而删去政治选择。支持自由讨论的理念与排除某些政治力量的行动之间存在需要解释的张力。\n\n评价应具体区分组织决定、个人主张和实际造成的伤害，不以伟大校长称号结束研究，也不因政治责任否定全部教育改革。将两者放回生涯，有助理解近代知识人为何在建国、秩序与自由之间作出有矛盾的选择。',
      'Cai also participated in Nationalist politics around 1927, rather than protecting scholarship from wholly outside politics. His relationship to the purge context should remain visible alongside educational contribution. Open discussion and political exclusion create a tension requiring explanation.\n\nOrganizational decisions, personal positions and resulting harm need distinction. Neither admiration as a university president nor political criticism should erase the other dimension of his career.', ['split-1927', 'republic-sources', 'mayfourth-archives']),
  ],
  'he-zhen': [
    d('把女性问题放回劳动和经济', 'Women’s emancipation, labor and economic relations',
      '何震的无政府主义女性论述不只要求女子受教育或参加国家政治，还追问家庭依附、劳动分配及经济权力。她批评把妇女解放附属于国家强盛或男性改革者荣誉的思路，指出少数精英妇女获得机会不等于多数女性摆脱压迫。\n\n这一视角使晚清改革史超出男政治家和外交危机，进入雇佣劳动、家务与性别关系。其方案有激进社会改造取向，不能简单贴作后来某一国家或政党的既定路线，应保留当时思想竞争的开放性。',
      'He-Yin Zhen’s anarchist feminism examined household dependence, labor and economic power beyond education or formal political inclusion. She challenged emancipation subordinated to national strength or male reformers’ prestige, distinguishing elite opportunities from the condition of most women.\n\nThis perspective brings wages, domestic labor and gender into late-Qing history. Her radical program belongs to contemporary intellectual competition rather than a later party or state’s predetermined path.', ['hezhen', 'he-yin-study']),
    d('署名、资料缺口与思想遗产', 'Authorship, documentary gaps and intellectual legacy',
      '何震与刘师培的婚姻及共同活动曾影响后人对署名和贡献的判断。研究应让她的文本直接进入讨论，不能把女性思想自动归给丈夫，也不应在证据不足时为每篇匿名文章确定作者。编辑、翻译与重新出版帮助恢复可见性，同时仍须说明版本和解释。\n\n其后期生平与死亡时间资料不完整，本传保留未知，不用猜测补齐。承认传记空白并不意味着思想不重要，反而显示历史档案如何不均衡地保存不同人的生活，需要将确定文本与不确定人生细节明确分开。',
      'Marriage and collaboration with Liu Shipei affected later judgments about attribution. Her texts deserve direct attention without automatically assigning them to her husband or confidently identifying every anonymous contribution. Editing and translation restore visibility while requiring version awareness.\n\nHer later life and death remain incompletely documented here. Preserving unknowns distinguishes established writing from uncertain biography and reveals unequal archival preservation, rather than diminishing her intellectual importance.', ['hezhen', 'he-yin-study']),
  ],
};
